package com.shortner.agent.orchestration.controller;
import com.shortner.agent.orchestration.model.Stage; import com.shortner.agent.orchestration.service.OrchestrationService; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/workflows") public class OrchestrationController {private final OrchestrationService service;public OrchestrationController(OrchestrationService service){this.service=service;}@PostMapping public OrchestrationService.RunView start(@Valid @RequestBody StartRequest r){return service.view(service.start(r.scenario(),r.requirement()).getId());}@GetMapping("/{id}") public OrchestrationService.RunView get(@PathVariable long id){return service.view(id);}@GetMapping("/metrics") public OrchestrationService.Metrics metrics(){return service.metrics();}@PostMapping("/{id}/stages/{stage}/approve") public OrchestrationService.RunView approve(@PathVariable long id,@PathVariable Stage stage,@Valid @RequestBody Approval r){service.approve(id,stage,r.approver());return service.view(id);}@PostMapping("/{id}/stages/{stage}/execute") public OrchestrationService.RunView execute(@PathVariable long id,@PathVariable Stage stage,@Valid @RequestBody Execution r){service.execute(id,stage,r.success(),r.evidence());return service.view(id);}@PostMapping("/{id}/replan") public OrchestrationService.RunView replan(@PathVariable long id,@Valid @RequestBody Reason r){service.replan(id,r.reason());return service.view(id);}@PostMapping("/{id}/rollback") public OrchestrationService.RunView rollback(@PathVariable long id,@Valid @RequestBody Reason r){service.rollback(id,r.reason());return service.view(id);}public record StartRequest(@NotBlank String scenario,@NotBlank String requirement){}public record Approval(@NotBlank String approver){}public record Execution(boolean success,@NotBlank String evidence){}public record Reason(@NotBlank String reason){}}
